| 80 degrees | -0.115, -0.115, 0.915 | 0.25 | 35 | 0 |
| 110 degrees | -0.115, -0.115, 0.915 | 0.30 | 18 | 10 |
| 130 degrees | -0.104, -0.115, 0.948 | 0.20 | 25 | 10 |
| 145 degrees | -0.083, -0.115, 0.972 | 0.20 | 25 | 10 |
| 160 degrees | -0.063, -0.115, 0.991 | 0.20 | 25 | 10 |
